"""Executes only read-only guard preflight APIs, never main, pause or dispatch."""
from pathlib import Path
import ast,base64,hashlib,importlib.util,json,time,types
encoded=''
g=types.ModuleType('guard_readonly_preflight');exec(compile(base64.b64decode(encoded),'guard_readonly_preflight','exec'),g.__dict__)
g.require_final_bindings()
spec=importlib.util.spec_from_file_location('reviewed_pilot_host',g.HOST);host=importlib.util.module_from_spec(spec);spec.loader.exec_module(host)
g.verify_previous_owner();identity=g.validate_train_inputs(host)
phase_trees={}
for phase in ['standing','train','final_constant','final_stop']:
 actual=host.tree_hashes(g.SMOKE/phase);expected=host.read(g.SMOKE/(phase+'_immutable.sha256.json'));assert actual==expected
 phase_trees[phase]={'files':len(actual),'immutable_map_sha256':host.sha(g.SMOKE/(phase+'_immutable.sha256.json')),'unchanged':True}
receipt=host.read(g.SMOKE/'train/training_receipt.json')
print(json.dumps({'checked_unix':time.time(),'read_only':True,'guard_runtime_sha256':hashlib.sha256(base64.b64decode(encoded)).hexdigest(),'identity':identity,'previous_owner_checked':True,'exact_container_names_and_IDs_absent':8,'phase_tree_aliases':phase_trees,'input_and_smoke_contract_passed':True,'actual_smoke_updates':receipt['updates_completed'],'actual_smoke_wrapper_seconds':receipt['wall_seconds'],'actual_smoke_strict_reload':receipt['reload'],'dispatch_performed':False},indent=2))
